using ZonaMatch.Domain.Entities;

namespace ZonaMatch.Application.Interfaces
{
    // Reads transit summaries generated by etl/calculate_transit.sql. Returns empty lists when a zone has no
    // stops or the zone data has not been imported yet (DATOS-ZONAS-DOCKER.bat).
    public interface IZoneTransitRepository
    {
        // The same zone selection as GET /api/v1/zones/{slug}.
        Task<IReadOnlyList<ZoneTransitModeStops>> ListStopsAsync(string slug, CancellationToken cancellationToken = default);

        Task<IReadOnlyList<TransitLineDepartures>> ListDeparturesAsync(string slug, CancellationToken cancellationToken = default);
    }
}
